import { $getArray } from "../../DisplayObjectUtil";
import { Sound, SoundMixer } from "@next2d/media";
/**
 * @description 指定tagの情報を元に、MovieClipにサウンドを追加
 *              Add sound to MovieClip based on specified tag information
 *
 * @param  {MovieClip} movie_clip
 * @param  {Map} sound_map
 * @param  {array} sound_objects
 * @return {Promise}
 * @method
 * @public
 */
export const execute = async (movie_clip, sound_map, sound_objects) => {
    const loaderInfo = movie_clip.loaderInfo;
    if (!loaderInfo) {
        return;
    }
    const data = loaderInfo.data;
    if (!data) {
        return;
    }
    const characters = data.characters;
    for (let idx = 0; idx < sound_objects.length; ++idx) {
        const object = sound_objects[idx];
        if (!object) {
            continue;
        }
        const sounds = $getArray();
        for (let idx = 0; idx < object.sound.length; ++idx) {
            const tag = object.sound[idx];
            if (!tag) {
                continue;
            }
            const character = characters[tag.characterId];
            if (!character) {
                continue;
            }
            const sound = new Sound();
            sound.loopCount = tag.loopCount | 0;
            sound.volume = Math.min(SoundMixer.volume, tag.volume);
            await sound.$build(character);
            sounds.push(sound);
        }
        sound_map.set(object.frame, sounds);
    }
};
